var P2P={on:false,room:'',me:'',peers:{},after:0,out:[],t:0,gen:0,t0:0,fail:0,dead:{},tries:{}};
function p2pDead(k){var n=P2P.tries[k]=(P2P.tries[k]||0)+1;P2P.dead[k]=performance.now()+Math.min(600000,15000*Math.pow(4,n-1))} /* 안 붙는 상대는 15초 · 1분 · 4분 · 최대 10분 뒤 다시 */
var P2P_ICE=[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun1.l.google.com:19302'}];
function p2pOk(){return typeof RTCPeerConnection!=='undefined'&&!!(NET.cfg&&NET.cfg.p2p===1)}
function p2pHumans(){var n=0;for(var k in P2P.peers)if(P2P.peers[k].open)n++;NET.humans=n}
function p2pClose(k,quiet){var pr=P2P.peers[k];if(!pr)return;delete P2P.peers[k];try{pr.pc.close()}catch(e){}if(!quiet){delete NET.roster[k];try{netDrop(k)}catch(e){}p2pHumans()}}
function p2pStop(silent){var was=P2P.on,room=P2P.room,me=P2P.me;P2P.gen++;P2P.on=false;clearTimeout(P2P.t);for(var k in P2P.peers)p2pClose(k,true);P2P.peers={};NET.humans=0;
  if(was&&!silent&&me)try{lbReq('rpc/gf_p2p',{p_room:room||null,p_me:me,p_leave:true}).catch(function(){})}catch(e){}}
function p2pWatch(){if(!P2P.on)return;var now=performance.now();for(var k in P2P.peers){var pr=P2P.peers[k];if(pr.open&&now-(pr.rx||0)>6000){crumb('p2p:quiet');p2pClose(k)}}} /* 6초 동안 아무것도 안 오면(앱을 갑자기 끈 사람) 연결 정리 */
