function p2pStart(){p2pStop(true);P2P.gen++;P2P.on=true;P2P.room=NET.room?'f-'+NET.room:'';P2P.me=netId();P2P.peers={};P2P.after=-1;P2P.out=[];P2P.t0=performance.now();P2P.fail=0;
  NET.live=true;NET.topic='p2p';NET.roster={};NET.humans=0;NET.ws=null;crumb('p2p:start');p2pPoll()}
function p2pNext(){var wait=false,k;for(k in P2P.peers)if(!P2P.peers[k].open)wait=true;
  var iv=(P2P.out.length>0||performance.now()-P2P.t0<10000)?800:wait?2000:((NET.cfg&&+NET.cfg.p2pIv)||8000); /* 다 연결되면 8초마다(무료 전송량 아끼기) */P2P.t=setTimeout(p2pPoll,iv)}
function p2pPoll(){if(!P2P.on)return;var g=P2P.gen,out=P2P.out.splice(0,20);
  lbReq('rpc/gf_p2p',{p_room:P2P.room||null,p_me:P2P.me,p_out:out,p_after:P2P.after,p_per:NET.maxPer}).then(function(r){if(g!==P2P.gen||!P2P.on)return;
    if(!r||r.err){P2P.fail++;if(P2P.fail>4){crumb('p2p:down');p2pStop(true);NET.live=false;return}p2pNext();return}P2P.fail=0;
    if(r.top!=null)P2P.after=Math.max(+r.top||0,P2P.after); /* 예전 판 요청 건너뛰기 */
    if(r.room&&!P2P.room){P2P.room=r.room;var m=/(\d+)$/.exec(r.room);if(m)NET.shard=+m[1];setTimeout(function(){if(P2P.on&&mode==='multi'&&state==='play')try{netChanShow()}catch(e){}},2500)}
    (r.msg||[]).forEach(function(m){P2P.after=Math.max(P2P.after,+m.id||0);p2pSig(m.f,m.b)});
    var now=performance.now(),set={};(r.mem||[]).forEach(function(k){set[k]=1;if(!P2P.peers[k]&&P2P.me<k&&!(P2P.dead[k]>now))p2pOffer(k)});
    for(var k in P2P.peers){var pr=P2P.peers[k];if(!set[k]&&!pr.open&&now-pr.t0>10000)p2pClose(k)}
