  pc.ondatachannel=function(e){p2pDc(k,pr,e.channel)};
  setTimeout(function(){if(P2P.peers[k]===pr&&!pr.open){crumb('p2p:tmo');p2pDead(k);p2pClose(k)}},20000); /* 느린 폰 · 사람 많을 때도 붙을 시간 20초, 안 붙으면 15초 뒤 다시 */
