  dc.onclose=function(){if(P2P.peers[k]===pr)p2pClose(k)}}
function p2pIce(pc){return new Promise(function(res){if(pc.iceGatheringState==='complete')return res();var t=setTimeout(res,2500);
  pc.addEventListener('icegatheringstatechange',function(){if(pc.iceGatheringState==='complete'){clearTimeout(t);res()}})})}
