function p2pSig(f,b){if(!b||!P2P.on||typeof f!=='string'||f===P2P.me)return;
  if(b.t==='o'&&typeof b.s==='string'){if(P2P.peers[f])p2pClose(f,true);var pr=p2pPc(f),pc=pr.pc;
    pc.setRemoteDescription({type:'offer',sdp:b.s}).then(function(){return pc.createAnswer()}).then(function(a){return pc.setLocalDescription(a)}).then(function(){return p2pIce(pc)})
      .then(function(){if(P2P.peers[f]!==pr)return;P2P.out.push({to:f,b:{t:'a',s:pc.localDescription.sdp}})}).catch(function(){p2pClose(f)})}
  else if(b.t==='a'&&typeof b.s==='string'){var p=P2P.peers[f];if(p&&p.pc.signalingState==='have-local-offer')p.pc.setRemoteDescription({type:'answer',sdp:b.s}).catch(function(){p2pClose(f)})}}
