import Foundation
import UIKit
import Capacitor
import GameKit

// 아가미파이터 1.1.12 Game Center: 조용히 로그인 → 기록 올리기 → 순위표 보기. 실패해도 게임은 그대로 진행.
@objc(GfGameCenterPlugin)
public class GfGameCenterPlugin: CAPPlugin, CAPBridgedPlugin, GKGameCenterControllerDelegate {
    public let identifier = "GfGameCenterPlugin"
    public let jsName = "GfGameCenter"
    public let pluginMethods: [CAPPluginMethod] = [
        CAPPluginMethod(name: "auth", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "submit", returnType: CAPPluginReturnPromise),
        CAPPluginMethod(name: "show", returnType: CAPPluginReturnPromise)
    ]
    private var authStarted = false
    private var authWaiters: [CAPPluginCall] = []

    private func finishAuth() {
        let ok = GKLocalPlayer.local.isAuthenticated
        let ws = authWaiters
        authWaiters = []
        for c in ws { c.resolve(["ok": ok, "name": ok ? GKLocalPlayer.local.displayName : ""]) }
    }

    @objc func auth(_ call: CAPPluginCall) {
        DispatchQueue.main.async {
            if GKLocalPlayer.local.isAuthenticated {
                call.resolve(["ok": true, "name": GKLocalPlayer.local.displayName])
                return
            }
            self.authWaiters.append(call)
            if self.authStarted { return }
            self.authStarted = true
            let interactive = call.getBool("interactive") ?? false
            GKLocalPlayer.local.authenticateHandler = { vc, _ in
                if let vc = vc {
                    if interactive, let root = self.bridge?.viewController {
                        root.present(vc, animated: true, completion: nil)
                        return
                    }
                }
                self.finishAuth()
            }
        }
    }

    @objc func submit(_ call: CAPPluginCall) {
        guard let id = call.getString("id") else { call.reject("no id"); return }
        let score = call.getInt("score") ?? 0
        if !GKLocalPlayer.local.isAuthenticated { call.resolve(["ok": false]); return }
        GKLeaderboard.submitScore(score, context: 0, player: GKLocalPlayer.local, leaderboardIDs: [id]) { err in
            if let e = err { call.resolve(["ok": false, "err": e.localizedDescription]) } else { call.resolve(["ok": true]) }
        }
    }

    @objc func show(_ call: CAPPluginCall) {
        DispatchQueue.main.async {
            guard let root = self.bridge?.viewController else { call.reject("no view"); return }
            if !GKLocalPlayer.local.isAuthenticated { call.resolve(["ok": false]); return }
            let vc: GKGameCenterViewController
            if let id = call.getString("id") {
                vc = GKGameCenterViewController(leaderboardID: id, playerScope: .global, timeScope: .allTime)
            } else {
                vc = GKGameCenterViewController(state: .leaderboards)
            }
            vc.gameCenterDelegate = self
            root.present(vc, animated: true, completion: nil)
            call.resolve(["ok": true])
        }
    }

    public func gameCenterViewControllerDidFinish(_ gameCenterViewController: GKGameCenterViewController) {
        gameCenterViewController.dismiss(animated: true, completion: nil)
    }
